function trimLayerByFrame(element,edge,direction){const scene=S.project.scenes.find(item=>item.id===element?.dataset.scene),layer=scene?.layers.find(item=>item.id===element?.dataset.layerclip);if(!scene||!layer)return;snapshot();const frame=1/S.project.fps,length=visibleDuration(layer,scene);if(edge==='right')layer.duration=Math.max(frame,Math.min(scene.duration-layer.start,length+direction*frame));else{const end=layer.start+length,next=Math.max(0,Math.min(end-frame,layer.start+direction*frame));if(layer.type==='video')layer.trimStart=Math.max(0,layer.trimStart+(next-layer.start)*layer.playbackRate);layer.start=next;layer.duration=end-next}select('layer',layer.id,{sceneId:scene.id});saveProject()}
