function staticNumber(value,fallback=0){return typeof value==='number'?value:fallback}
function renderStageOverlay(){const root=$('#stageOverlay');if(!root||S.selected.kind!=='layer'){if(root)root.innerHTML='';return}const layer=selectedLayer();if(!layer||!['text','shape','image','video'].includes(layer.type)){root.innerHTML='';return}const tx=staticNumber(layer.transform.x),ty=staticNumber(layer.transform.y),sx=Math.abs(staticNumber(layer.transform.scaleX,1)),sy=Math.abs(staticNumber(layer.transform.scaleY,1)),x=layer.x+tx,y=layer.y+ty,w=Math.max(1,layer.width*sx),h=Math.max(1,layer.height*sy);root.innerHTML='<div class="stage-selection" data-stage-layer="'+esc(layer.id)+'" data-label="'+esc(layer.id)+'" style="left:'+x/S.project.width*100+'%;top:'+y/S.project.height*100+'%;width:'+w/S.project.width*100+'%;height:'+h/S.project.height*100+'%"><span class="stage-handle nw" data-stage-handle="nw"></span><span class="stage-handle ne" data-stage-handle="ne"></span><span class="stage-handle sw" data-stage-handle="sw"></span><span class="stage-handle se" data-stage-handle="se"></span></div>';const box=root.firstElementChild;box.onpointerdown=event=>startStageDrag(event,box)}
