function resizeStageByFrame(handle,key,amount){const layer=selectedLayer();if(!layer)return;snapshot();const dx=key==='ArrowLeft'?-amount:key==='ArrowRight'?amount:0,dy=key==='ArrowUp'?-amount:key==='ArrowDown'?amount:0,min=8;if(handle.includes('e'))layer.width=Math.max(min,Math.min(S.project.width-layer.x,layer.width+dx));if(handle.includes('s'))layer.height=Math.max(min,Math.min(S.project.height-layer.y,layer.height+dy));if(handle.includes('w')){const next=Math.max(0,Math.min(layer.x+layer.width-min,layer.x+dx));layer.width+=layer.x-next;layer.x=next}if(handle.includes('n')){const next=Math.max(0,Math.min(layer.y+layer.height-min,layer.y+dy));layer.height+=layer.y-next;layer.y=next}saveProject();renderInspector();renderStageOverlay()}
